1	using System.Text.Json;
2	using System.Reflection;
3	using System.Text;
4	using System.Globalization;
5	using NumWordify.Models;
6	
7	namespace NumWordify.Converters;
8	
9	/// <summary>
10	/// Provides functionality to convert numbers to their word representation based on localization settings.
11	/// </summary>
12	public class NumberToWordsConverter
13	{
14	    private readonly LocalizationModel _localization;
15	    private CurrencyModel? _overriddenCurrency;
16	
17	    /// <summary>
18	    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class using the specified culture.
19	    /// </summary>
20	    /// <param name="culture">The culture code to use for localization (e.g., "en-US").</param>
21	    /// <exception cref="FileNotFoundException">Thrown when the localization file for the specified culture is not found.</exception>
22	    /// <exception cref="InvalidOperationException">Thrown when deserialization of localization data fails.</exception>
23	    public NumberToWordsConverter(string culture)
24	    {
25	        var assembly = typeof(NumberToWordsConverter).Assembly;
26	        var resourceName = $"{culture}.json";
27	
28	        // List all resources for debugging
29	        var resources = assembly.GetManifestResourceNames();
30	
31	        if (!resources.Contains(resourceName))
32	        {
33	            var availableCultures = resources
34	                .Where(r => r.EndsWith(".json"))
35	                .Select(r => r.Replace(".json", ""))
36	                .ToList();
37	
38	            throw new FileNotFoundException(
39	                $"Localization file not found for culture: {culture}. " +
40	                $"Available cultures: {string.Join(", ", availableCultures)}");
41	        }
42	
43	        using var stream = assembly.GetManifestResourceStream(resourceName);
44	        if (stream == null)
45	            throw new FileNotFoundException($"Failed to load resource stream for culture: {culture}");
46	
47	        using var reader = new StreamReader(stream, Encoding.UTF8);
48	        var jsonContent = reader.ReadToEnd();
49	
50	        try
51	        {
52	            _localization = JsonSerializer.Deserialize<LocalizationModel>(jsonContent)
53	                ?? throw new InvalidOperationException("Failed to deserialize localization data");
54	
55	            // Validate individual properties
56	            if (_localization.Numbers == null)
57	                throw new InvalidOperationException("Numbers property is null");
58	            if (_localization.Currency == null)
59	                throw new InvalidOperationException("Currency property is null");
60	            if (_localization.Settings == null)
61	                throw new InvalidOperationException("Settings property is null");
62	        }
63	        catch (JsonException ex)
64	        {
65	            throw new InvalidOperationException($"Failed to parse localization data for culture {culture}: {ex.Message}");
66	        }
67	
68	        ValidateLocalization();
69	    }
70	
71	    /// <summary>
72	    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class using the specified localization model.
73	    /// </summary>
74	    /// <param name="localization">The localization model to use for number conversion.</param>
75	    /// <exception cref="InvalidOperationException">Thrown when the localization model is invalid.</exception>
76	    public NumberToWordsConverter(LocalizationModel localization)
77	    {
78	        _localization = localization;
79	        ValidateLocalization();
80	    }
81	
82	    /// <summary>
83	    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class using the specified CultureInfo.
84	    /// </summary>
85	    /// <param name="cultureInfo">The CultureInfo to use for localization.</param>
86	    /// <exception cref="FileNotFoundException">Thrown when the localization file for the specified culture is not found.</exception>
87	    /// <exception cref="InvalidOperationException">Thrown when deserialization of localization data fails.</exception>
88	    public NumberToWordsConverter(CultureInfo cultureInfo) : this(cultureInfo.Name)
89	    {
90	    }
91	
92	    /// <summary>
93	    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class using the specified culture and currency.
94	    /// </summary>
95	    /// <param name="culture">The culture code to use for localization (e.g., "tr-TR").</param>
96	    /// <param name="currency">The currency model to override the default currency.</param>
97	    public NumberToWordsConverter(string culture, CurrencyModel currency) : this(culture)
98	    {
99	        _overriddenCurrency = currency;
100	    }
101	
102	    /// <summary>
103	    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class using the specified CultureInfo and currency.
104	    /// </summary>
105	    /// <param name="cultureInfo">The CultureInfo to use for localization.</param>
106	    /// <param name="currency">The currency model to override the default currency.</param>
107	    public NumberToWordsConverter(CultureInfo cultureInfo, CurrencyModel currency) : this(cultureInfo)
108	    {
109	        _overriddenCurrency = currency;
110	    }
111	
112	    /// <summary>
113	    /// Gets the current currency model being used for conversion.
114	    /// </summary>
115	    private CurrencyModel CurrentCurrency => _overriddenCurrency ?? _localization.Currency;
116	
117	    private void ValidateLocalization()
118	    {
119	        if (_localization.Numbers.Ones.Length != 10)
120	            throw new InvalidOperationException("Ones array must contain exactly 10 elements");
121	
122	        if (_localization.Numbers.Tens.Length != 10)
123	            throw new InvalidOperationException("Tens array must contain exactly 10 elements");
124	
125	        if (_localization.Numbers.Hundreds.Length != 10)
126	            throw new InvalidOperationException("Hundreds array must contain exactly 10 elements");
127	
128	        if (_localization.Numbers.Scales == null || _localization.Numbers.Scales.Length == 0)
129	            throw new InvalidOperationException("Scales array must contain at least 1 element");
130	
131	        if (string.IsNullOrEmpty(_localization.Settings.CurrencyFormat))
132	            throw new InvalidOperationException("Currency format must be specified");
133	
134	        if (string.IsNullOrEmpty(_localization.Settings.ZeroWord))
135	            throw new InvalidOperationException("Zero word must be specified");
136	
137	        if (string.IsNullOrEmpty(_localization.Settings.NegativeWord))
138	            throw new InvalidOperationException("Negative word must be specified");
139	
140	        if (string.IsNullOrEmpty(_localization.Settings.NumberFormat))
141	            throw new InvalidOperationException("Number format must be specified");
142	    }
143	
144	    /// <summary>
145	    /// Converts a decimal number to its word representation including currency.
146	    /// </summary>
147	    /// <param name="number">The decimal number to convert.</param>
148	    /// <returns>A string representing the number in words with currency.</returns>
149	    public string Convert(decimal number)
150	    {
151	        var (isNegative, wholePart, decimalPart) = SplitNumberParts(number);
152	
153	        var wholeWords = ConvertWholeNumber(wholePart);
154	        var decimalWords = ConvertWholeNumber(decimalPart);
155	
156	        if (string.IsNullOrEmpty(wholeWords))
157	            wholeWords = _localization.Settings.ZeroWord;
158	
159	        if (string.IsNullOrEmpty(decimalWords))
160	            decimalWords = _localization.Settings.ZeroWord;
161	
162	        var result = _localization.Settings.CurrencyFormat
163	            .Replace("{whole}", wholeWords)
164	            .Replace("{major}", CurrentCurrency.Major)
165	            .Replace("{decimal}", decimalWords)
166	            .Replace("{minor}", CurrentCurrency.Minor)
167	            .Trim();
168	
169	        return isNegative ? $"{_localization.Settings.NegativeWord} {result}" : result;
170	    }
171	
172	    /// <summary>
173	    /// Converts a decimal number to its word representation without including currency.
174	    /// </summary>
175	    /// <param name="number">The decimal number to convert.</param>
176	    /// <returns>A string representing the number in words without currency.</returns>
177	    public string ConvertWithoutCurrency(decimal number)
178	    {
179	        var (isNegative, wholePart, decimalPart) = SplitNumberParts(number);
180	
181	        var wholeWords = ConvertWholeNumber(wholePart);
182	        var decimalWords = ConvertWholeNumber(decimalPart);
183	
184	        if (string.IsNullOrEmpty(wholeWords))
185	            wholeWords = _localization.Settings.ZeroWord;
186	
187	        if (string.IsNullOrEmpty(decimalWords))
188	            decimalWords = _localization.Settings.ZeroWord;
189	
190	        var result = _localization.Settings.NumberFormat
191	            .Replace("{whole}", wholeWords)
192	            .Replace("{decimal}", decimalWords)
193	            .Trim();
194	
195	        return isNegative ? $"{_localization.Settings.NegativeWord} {result}" : result;
196	    }
197	
198	    private string ConvertWholeNumber(decimal number)
199	    {
200	        if (number < 0)
201	            throw new ArgumentException("Number should be positive in ConvertWholeNumber");
202	
203	        if (number == 0)
204	            return "";
205	
206	        var groups = new List<string>();
207	        var currentNumber = number;
208	        _currentScale = 0;
209	
210	        while (currentNumber > 0)
211	        {
212	            var group = (int)(currentNumber % 1000);
213	            if (group > 0)
214	            {
215	                var groupText = ConvertGroup(group);
216	                if (_currentScale > 0)
217	                {
218	                    if (_currentScale >= _localization.Numbers.Scales.Length)
219	                        throw new InvalidOperationException("Number is too large to convert with the current locale scale configuration.");
220	
221	                    groupText += " " + _localization.Numbers.Scales[_currentScale];
222	                }
223	                groups.Insert(0, groupText.Trim());
224	            }
225	
226	            currentNumber = Math.Floor(currentNumber / 1000);
227	            _currentScale++;
228	        }
229	
230	        return string.Join(" ", groups);
231	    }
232	
233	    private string ConvertGroup(int number)
234	    {
235	        var result = new List<string>();
236	
237	        // Yüzler basamağı
238	        var hundreds = number / 100;
239	        if (hundreds > 0)
240	        {
241	            if (_localization.Settings.SkipOneForHundred && hundreds == 1)
242	                result.Add(_localization.Numbers.Hundreds[1]);
243	            else
244	                result.Add(_localization.Numbers.Hundreds[hundreds]);
245	        }
246	
247	        // Onlar ve birler basamağı
248	        var remainder = number % 100;
249	
250	        // Özel sayılar için kontrol (11-19 arası)
251	        if (remainder >= 11 && remainder <= 19 &&
252	            _localization.Settings.UseTeens &&
253	            _localization.SpecialNumbers?.Teens != null)
254	        {
255	            result.Add(_localization.SpecialNumbers.Teens[remainder - 11]);
256	            return string.Join(" ", result);
257	        }
258	
259	        // Özel sayılar sözlüğünde varsa direkt kullan
260	        if (_localization.SpecialNumbers?.Special?.ContainsKey(remainder) == true)
261	        {
262	            result.Add(_localization.SpecialNumbers.Special[remainder]);
263	            return string.Join(" ", result);
264	        }
265	
266	        var tens = remainder / 10;
267	        var ones = remainder % 10;
268	
269	        if (tens > 0)
270	        {
271	            var tensWord = _localization.Numbers.Tens[tens];
272	
273	            // Birler basamağı varsa ve compound numbers kullanılıyorsa
274	            if (ones > 0 && _localization.Settings.UseCompoundNumbers)
275	            {
276	                var separator = _localization.SpecialNumbers?.CompoundSeparator ?? " ";
277	                tensWord += separator + _localization.Numbers.Ones[ones];
278	                result.Add(tensWord);
279	            }
280	            else
281	            {
282	                result.Add(tensWord);
283	            }
284	        }
285	        // Sadece birler basamağı varsa
286	        else if (ones > 0 && !(_localization.Settings.SkipOneForThousand &&
287	            ones == 1 && number == 1 && _currentScale == 1))
288	        {
289	            result.Add(_localization.Numbers.Ones[ones]);
290	        }
291	
292	        return string.Join(" ", result).Trim();
293	    }
294	
295	    private static (bool isNegative, decimal wholePart, decimal decimalPart) SplitNumberParts(decimal number)
296	    {
297	        var isNegative = number < 0;
298	        number = Math.Abs(number);
299	
300	        var wholePart = Math.Floor(number);
301	        var decimalPart = Math.Round((number - wholePart) * 100);
302	
303	        if (decimalPart == 100)
304	        {
305	            wholePart += 1;
306	            decimalPart = 0;
307	        }
308	
309	        return (isNegative, wholePart, decimalPart);
310	    }
311	
312	    private int _currentScale = 0;
313	}
