namespace NumWordify.Exceptions;

/// <summary>
/// Base class for every error raised by NumWordify. Catch this type to handle
/// all library failures without also catching unrelated framework exceptions.
/// </summary>
public class NumWordifyException : Exception
{
    /// <summary>
    /// Initializes a new instance of the <see cref="NumWordifyException"/> class.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    public NumWordifyException(string message) : base(message)
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumWordifyException"/> class.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    /// <param name="innerException">The exception that caused this error.</param>
    public NumWordifyException(string message, Exception? innerException) : base(message, innerException)
    {
    }
}

/// <summary>
/// Thrown when no embedded localization resource matches the requested culture.
/// </summary>
public sealed class LocalizationNotFoundException : NumWordifyException
{
    /// <summary>
    /// Initializes a new instance of the <see cref="LocalizationNotFoundException"/> class.
    /// </summary>
    /// <param name="culture">The culture that could not be resolved.</param>
    /// <param name="availableCultures">The cultures shipped with the library.</param>
    public LocalizationNotFoundException(string culture, IReadOnlyList<string> availableCultures)
        : base($"Localization not found for culture '{culture}'. Available cultures: {string.Join(", ", availableCultures)}.")
    {
        Culture = culture;
        AvailableCultures = availableCultures;
    }

    /// <summary>Gets the culture that could not be resolved.</summary>
    public string Culture { get; }

    /// <summary>Gets the cultures shipped with the library.</summary>
    public IReadOnlyList<string> AvailableCultures { get; }
}

/// <summary>
/// Thrown when a localization model is structurally invalid — either because an
/// embedded resource could not be parsed or because a caller-supplied
/// <see cref="Models.LocalizationModel"/> is incomplete.
/// </summary>
public sealed class InvalidLocalizationException : NumWordifyException
{
    /// <summary>
    /// Initializes a new instance of the <see cref="InvalidLocalizationException"/> class.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    public InvalidLocalizationException(string message) : base(message)
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="InvalidLocalizationException"/> class.
    /// </summary>
    /// <param name="message">The message that describes the error.</param>
    /// <param name="innerException">The exception that caused this error.</param>
    public InvalidLocalizationException(string message, Exception? innerException) : base(message, innerException)
    {
    }
}

/// <summary>
/// Thrown when a number is larger than the scale words configured for the locale
/// can express. See <see cref="Models.NumbersModel.Scales"/>.
/// </summary>
public sealed class NumberOutOfRangeException : NumWordifyException
{
    /// <summary>
    /// Initializes a new instance of the <see cref="NumberOutOfRangeException"/> class.
    /// </summary>
    /// <param name="value">The number that could not be converted.</param>
    /// <param name="maximumScaleCount">The number of scale words the locale defines.</param>
    public NumberOutOfRangeException(decimal value, int maximumScaleCount)
        : base($"The number {value} is too large for this locale: it defines {maximumScaleCount} scale word(s), " +
               $"so the largest convertible value is 10^{maximumScaleCount * 3} - 1.")
    {
        Value = value;
        MaximumScaleCount = maximumScaleCount;
    }

    /// <summary>Gets the number that could not be converted.</summary>
    public decimal Value { get; }

    /// <summary>Gets the number of scale words the locale defines.</summary>
    public int MaximumScaleCount { get; }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// Represents the complete localization ruleset for one language: its number
/// words, its formatting settings and the currencies it knows how to name.
/// </summary>
public class LocalizationModel
{
    /// <summary>
    /// Gets or sets the default currency used by <c>Convert</c> when no override is supplied.
    /// </summary>
    [JsonPropertyName("currency")]
    public CurrencyModel? Currency { get; set; }

    /// <summary>
    /// Gets or sets additional currencies this locale can name, keyed by ISO 4217 code
    /// (for example <c>"EUR"</c>). Lets a single locale file serve several currencies
    /// instead of duplicating the whole file per currency.
    /// </summary>
    [JsonPropertyName("currencies")]
    public Dictionary<string, CurrencyModel>? Currencies { get; set; }

    /// <summary>
    /// Gets or sets the number words for this locale.
    /// </summary>
    [JsonPropertyName("numbers")]
    public NumbersModel? Numbers { get; set; }

    /// <summary>
    /// Gets or sets the formatting settings for this locale.
    /// </summary>
    [JsonPropertyName("settings")]
    public SettingsModel Settings { get; set; } = new();

    /// <summary>
    /// Gets or sets the irregular number words for this locale.
    /// </summary>
    [JsonPropertyName("specialNumbers")]
    public SpecialNumbersModel? SpecialNumbers { get; set; }

    /// <summary>
    /// Initializes a new instance of the <see cref="LocalizationModel"/> class.
    /// </summary>
    public LocalizationModel()
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="LocalizationModel"/> class.
    /// </summary>
    /// <param name="currency">The default currency.</param>
    /// <param name="numbers">The number words.</param>
    /// <param name="settings">Optional formatting settings.</param>
    public LocalizationModel(CurrencyModel currency, NumbersModel numbers, SettingsModel? settings = null)
    {
        Currency = currency;
        Numbers = numbers;
        Settings = settings ?? new SettingsModel();
    }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// Names the major and minor unit of a currency.
/// </summary>
/// <remarks>
/// <see cref="MajorSingular"/> and <see cref="MinorSingular"/> are optional. When set,
/// they are used whenever the corresponding numeric part equals one, so that
/// <c>1.01</c> reads "ONE DOLLAR ONE CENT" instead of "ONE DOLLARS ONE CENTS".
/// Languages that do not inflect currency names (Turkish, for example) simply omit them.
/// </remarks>
public class CurrencyModel
{
    /// <summary>
    /// Gets or sets the major currency unit (for example <c>"DOLLARS"</c>).
    /// </summary>
    [JsonPropertyName("major")]
    public string Major { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the minor currency unit (for example <c>"CENTS"</c>).
    /// </summary>
    [JsonPropertyName("minor")]
    public string Minor { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the singular form of <see cref="Major"/>, used when the whole part is one.
    /// Falls back to <see cref="Major"/> when not set.
    /// </summary>
    [JsonPropertyName("majorSingular")]
    public string? MajorSingular { get; set; }

    /// <summary>
    /// Gets or sets the singular form of <see cref="Minor"/>, used when the fractional part is one.
    /// Falls back to <see cref="Minor"/> when not set.
    /// </summary>
    [JsonPropertyName("minorSingular")]
    public string? MinorSingular { get; set; }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// The number words of a locale. <see cref="Ones"/>, <see cref="Tens"/> and
/// <see cref="Hundreds"/> are indexed by digit and must contain exactly ten entries,
/// with index zero left empty.
/// </summary>
public class NumbersModel
{
    /// <summary>
    /// Gets or sets the words for the ones digit. Index 0 must be empty.
    /// </summary>
    [JsonPropertyName("ones")]
    public string[] Ones { get; set; } = [];

    /// <summary>
    /// Gets or sets the words for the tens digit. Index 0 must be empty.
    /// </summary>
    [JsonPropertyName("tens")]
    public string[] Tens { get; set; } = [];

    /// <summary>
    /// Gets or sets the words for the hundreds digit. Index 0 must be empty.
    /// </summary>
    [JsonPropertyName("hundreds")]
    public string[] Hundreds { get; set; } = [];

    /// <summary>
    /// Gets or sets the hundreds words used when the last two digits are zero.
    /// Optional; falls back to <see cref="Hundreds"/>.
    /// </summary>
    /// <remarks>
    /// Spanish needs this for <c>100 = CIEN</c> versus <c>101 = CIENTO UNO</c>, and French
    /// for <c>200 = DEUX CENTS</c> versus <c>250 = DEUX CENT CINQUANTE</c>. When set it must
    /// contain exactly ten entries. See <see cref="SettingsModel.UseExactHundredsBeforeScale"/>
    /// for how it interacts with scale words.
    /// </remarks>
    [JsonPropertyName("exactHundreds")]
    public string[]? ExactHundreds { get; set; }

    /// <summary>
    /// Gets or sets the scale words: index 0 is the units group, index 1 the thousands
    /// group, and so on. The array length caps the largest convertible number at
    /// 10^(3 × length) − 1.
    /// </summary>
    [JsonPropertyName("scales")]
    public string[] Scales { get; set; } = [];

    /// <summary>
    /// Gets or sets the plural scale words, used when the group preceding the scale is
    /// greater than one (French <c>DEUX MILLIONS</c>, Spanish <c>DOS MILLONES</c>).
    /// Optional; falls back to <see cref="Scales"/>. When set it must have the same
    /// length as <see cref="Scales"/>.
    /// </summary>
    [JsonPropertyName("scalesPlural")]
    public string[]? ScalesPlural { get; set; }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// How the fractional part of a number is read out by
/// <see cref="Converters.INumberToWordsConverter.ConvertWithoutCurrency(decimal)"/>.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum DecimalReadingMode
{
    /// <summary>
    /// Read the fraction as a whole number of <see cref="SettingsModel.DecimalPlaces"/> digits,
    /// the way money is read: <c>1.5</c> becomes "ONE POINT FIFTY" (fifty hundredths).
    /// This is the default and matches how the currency format reads minor units.
    /// </summary>
    Fraction = 0,

    /// <summary>
    /// Read the fraction digit by digit, the way a plain number is normally spoken:
    /// <c>1.5</c> becomes "ONE POINT FIVE" and <c>1.25</c> becomes "ONE POINT TWO FIVE".
    /// Digits beyond <see cref="SettingsModel.DecimalPlaces"/> are still rounded away.
    /// </summary>
    Digits = 1,
}

/// <summary>
/// Formatting rules for a locale.
/// </summary>
public class SettingsModel
{
    /// <summary>
    /// Gets or sets a value indicating whether the word for "one" is dropped in front of the
    /// thousands scale word (Turkish <c>BİN</c> rather than <c>BİR BİN</c>, French <c>MILLE</c>
    /// rather than <c>UN MILLE</c>). Only affects the thousands group.
    /// </summary>
    [JsonPropertyName("skipOneForThousand")]
    public bool SkipOneForThousand { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether special words are used for 11–19.
    /// </summary>
    /// <remarks>
    /// Leave unset (the default) to decide automatically: teens are used whenever
    /// <see cref="SpecialNumbersModel.Teens"/> is supplied. Set it to <see langword="false"/>
    /// to force regular construction even though teens are present.
    /// </remarks>
    [JsonPropertyName("useTeens")]
    public bool? UseTeens { get; set; }

    /// <summary>
    /// Gets or sets a value indicating whether <see cref="NumbersModel.ExactHundreds"/> also
    /// applies to groups followed by a scale word. Defaults to <see langword="true"/>.
    /// </summary>
    /// <remarks>
    /// Spanish keeps the exact form everywhere (<c>CIEN MIL</c>), so it leaves this on.
    /// French drops the plural before a scale word (<c>DEUX CENTS</c> but <c>DEUX CENT MILLE</c>),
    /// so it sets this to <see langword="false"/>.
    /// </remarks>
    [JsonPropertyName("useExactHundredsBeforeScale")]
    public bool UseExactHundredsBeforeScale { get; set; } = true;

    /// <summary>
    /// Gets or sets the word placed in front of negative numbers.
    /// </summary>
    [JsonPropertyName("negativeWord")]
    public string NegativeWord { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the word used for zero.
    /// </summary>
    [JsonPropertyName("zeroWord")]
    public string ZeroWord { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the template used by <c>Convert</c>. Supports the placeholders
    /// <c>{whole}</c>, <c>{major}</c>, <c>{decimal}</c> and <c>{minor}</c>.
    /// </summary>
    [JsonPropertyName("currencyFormat")]
    public string CurrencyFormat { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets the template used by <c>ConvertWithoutCurrency</c>. Supports the
    /// placeholders <c>{whole}</c> and <c>{decimal}</c>.
    /// </summary>
    [JsonPropertyName("numberFormat")]
    public string NumberFormat { get; set; } = string.Empty;

    /// <summary>
    /// Gets or sets how many fractional digits are kept. Defaults to 2 (minor currency
    /// units). Use 0 for currencies without a minor unit and 3 for currencies such as
    /// the Tunisian dinar. Must be between 0 and 6.
    /// </summary>
    [JsonPropertyName("decimalPlaces")]
    public int DecimalPlaces { get; set; } = 2;

    /// <summary>
    /// Gets or sets how the fractional part is read by <c>ConvertWithoutCurrency</c>.
    /// Defaults to <see cref="DecimalReadingMode.Fraction"/>. The currency format always
    /// reads the fraction as minor units regardless of this setting.
    /// </summary>
    [JsonPropertyName("decimalReading")]
    public DecimalReadingMode DecimalReading { get; set; } = DecimalReadingMode.Fraction;

    /// <summary>
    /// No longer used. The ones digit is always written; the separator between the tens
    /// and ones word comes from <see cref="SpecialNumbersModel.CompoundSeparator"/>.
    /// </summary>
    [Obsolete("Has no effect. The ones digit is always written; set SpecialNumbers.CompoundSeparator to control the separator. This property will be removed in 3.0.")]
    [JsonPropertyName("useCompoundNumbers")]
    public bool UseCompoundNumbers { get; set; }

    /// <summary>
    /// No longer used. Whether a locale says "one hundred" or just "hundred" is decided by
    /// the value stored at index 1 of <see cref="NumbersModel.Hundreds"/>.
    /// </summary>
    [Obsolete("Has no effect. Set Numbers.Hundreds[1] to the desired wording instead. This property will be removed in 3.0.")]
    [JsonPropertyName("skipOneForHundred")]
    public bool SkipOneForHundred { get; set; }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// Irregular number words that cannot be built from the ones/tens/hundreds arrays.
/// </summary>
public class SpecialNumbersModel
{
    /// <summary>
    /// Gets or sets the words for 11 through 19, in order. When supplied it must contain
    /// exactly nine entries.
    /// </summary>
    [JsonPropertyName("teens")]
    public string[]? Teens { get; set; }

    /// <summary>
    /// Gets or sets whole-word overrides for the last two digits of a group, keyed by the
    /// value 1–99.
    /// </summary>
    /// <remarks>
    /// This is how vigesimal and fused forms are expressed: French <c>71 = SOIXANTE ET ONZE</c>
    /// and <c>80 = QUATRE-VINGTS</c>, Spanish <c>21 = VEINTIUNO</c>. An entry here wins over
    /// <see cref="Teens"/> and over regular construction. Key 0 is never consulted, because a
    /// group whose last two digits are zero contributes no tens/ones word at all.
    /// </remarks>
    [JsonPropertyName("special")]
    public Dictionary<int, string>? Special { get; set; }

    /// <summary>
    /// Gets or sets overrides that apply only when the group is followed by a scale word,
    /// keyed by the value 1–99.
    /// </summary>
    /// <remarks>
    /// Spanish apocopates before a scale word: <c>1.000.000 = UN MILLÓN</c> (not <c>UNO</c>)
    /// and <c>21.000.000 = VEINTIÚN MILLONES</c> (not <c>VEINTIUNO</c>). Checked before
    /// <see cref="Special"/>, but after <see cref="SettingsModel.SkipOneForThousand"/>.
    /// </remarks>
    [JsonPropertyName("specialBeforeScale")]
    public Dictionary<int, string>? SpecialBeforeScale { get; set; }

    /// <summary>
    /// Gets or sets the separator placed between the tens and ones word
    /// (<c>"-"</c> for English "TWENTY-ONE", <c>" Y "</c> for Spanish "TREINTA Y UNO").
    /// Defaults to a single space.
    /// </summary>
    [JsonPropertyName("compoundSeparator")]
    public string CompoundSeparator { get; set; } = " ";
}

using System.Collections.Concurrent;
using System.Reflection;
using System.Text;
using System.Text.Json;
using NumWordify.Exceptions;
using NumWordify.Models;

namespace NumWordify.Converters;

/// <summary>
/// Loads embedded localization resources and caches the parsed, validated models.
/// </summary>
/// <remarks>
/// Parsing a locale costs an assembly manifest scan, a stream read and a full JSON
/// deserialization. Doing that per call made <c>ToWords</c> roughly twenty-five times
/// slower than necessary, so every parsed model is cached here for the lifetime of the
/// process. The cached instances are never handed out to callers, which is what makes
/// sharing them safe.
/// </remarks>
internal static class LocalizationLoader
{
    private const string ResourceSuffix = ".json";

    private static readonly JsonSerializerOptions SerializerOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true,
    };

    private static readonly Lazy<string[]> ResourceNames = new(() =>
        typeof(LocalizationLoader).GetTypeInfo().Assembly
            .GetManifestResourceNames()
            .Where(name => name.EndsWith(ResourceSuffix, StringComparison.OrdinalIgnoreCase))
            .OrderBy(name => name.Length)
            .ThenBy(name => name, StringComparer.Ordinal)
            .ToArray());

    private static readonly Lazy<IReadOnlyList<string>> AvailableCultureNames = new(() =>
        ResourceNames.Value
            .Select(name => name.Substring(0, name.Length - ResourceSuffix.Length))
            .OrderBy(name => name, StringComparer.Ordinal)
            .ToArray());

    private static readonly ConcurrentDictionary<string, LocalizationModel> Cache =
        new(StringComparer.Ordinal);

    /// <summary>
    /// Gets the culture names shipped with the library, sorted alphabetically.
    /// </summary>
    public static IReadOnlyList<string> AvailableCultures => AvailableCultureNames.Value;

    /// <summary>
    /// Determines whether a localization resource can be resolved for the given culture.
    /// </summary>
    public static bool IsSupported(string? culture) =>
        !string.IsNullOrWhiteSpace(culture) && TryResolveResourceName(culture!, out _);

    /// <summary>
    /// Returns the cached, validated localization for the given culture.
    /// </summary>
    /// <exception cref="ArgumentException">The culture is null, empty or whitespace.</exception>
    /// <exception cref="LocalizationNotFoundException">No resource matches the culture.</exception>
    /// <exception cref="InvalidLocalizationException">The resource could not be parsed or is invalid.</exception>
    public static LocalizationModel Load(string culture)
    {
        if (culture is null)
            throw new ArgumentNullException(nameof(culture));

        if (culture.Length == 0 || string.IsNullOrWhiteSpace(culture))
        {
            throw new ArgumentException(
                "Culture must be a non-empty culture name such as \"en-US\". " +
                "CultureInfo.InvariantCulture has an empty name and cannot be used; " +
                $"supported cultures are: {string.Join(", ", AvailableCultures)}.",
                nameof(culture));
        }

        if (!TryResolveResourceName(culture, out var resourceName))
            throw new LocalizationNotFoundException(culture, AvailableCultures);

        return Cache.GetOrAdd(resourceName, Parse);
    }

    /// <summary>
    /// Resolves a culture name to an embedded resource name. Matching is case-insensitive
    /// and falls back from a specific culture to any variant of the same language, so
    /// <c>"EN-US"</c>, <c>"en"</c> and <c>"en-GB"</c> all resolve to <c>en-US.json</c>.
    /// </summary>
    private static bool TryResolveResourceName(string culture, out string resourceName)
    {
        var names = ResourceNames.Value;

        var exact = culture + ResourceSuffix;
        foreach (var name in names)
        {
            if (string.Equals(name, exact, StringComparison.OrdinalIgnoreCase))
            {
                resourceName = name;
                return true;
            }
        }

        // "en" -> "en-US.json"; also "en-GB" -> "en" -> "en-US.json".
        var language = culture;
        var separatorIndex = culture.IndexOf('-');
        if (separatorIndex > 0)
        {
            language = culture.Substring(0, separatorIndex);

            var languageOnly = language + ResourceSuffix;
            foreach (var name in names)
            {
                if (string.Equals(name, languageOnly, StringComparison.OrdinalIgnoreCase))
                {
                    resourceName = name;
                    return true;
                }
            }
        }

        // ResourceNames is ordered shortest-first, so "tr" picks tr-TR.json over tr-TR-EUR.json.
        var prefix = language + "-";
        foreach (var name in names)
        {
            if (name.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            {
                resourceName = name;
                return true;
            }
        }

        resourceName = string.Empty;
        return false;
    }

    private static LocalizationModel Parse(string resourceName)
    {
        var assembly = typeof(LocalizationLoader).GetTypeInfo().Assembly;

        string json;
        using (var stream = assembly.GetManifestResourceStream(resourceName))
        {
            if (stream is null)
            {
                throw new InvalidLocalizationException(
                    $"The embedded resource '{resourceName}' could not be opened.");
            }

            using var reader = new StreamReader(stream, Encoding.UTF8);
            json = reader.ReadToEnd();
        }

        LocalizationModel? model;
        try
        {
            model = JsonSerializer.Deserialize<LocalizationModel>(json, SerializerOptions);
        }
        catch (JsonException ex)
        {
            throw new InvalidLocalizationException(
                $"The embedded resource '{resourceName}' is not valid JSON: {ex.Message}", ex);
        }

        if (model is null)
        {
            throw new InvalidLocalizationException(
                $"The embedded resource '{resourceName}' deserialized to null.");
        }

        LocalizationValidator.Validate(model, resourceName);
        return model;
    }
}

using NumWordify.Exceptions;
using NumWordify.Models;

namespace NumWordify.Converters;

/// <summary>
/// Checks that a localization model is complete enough to convert every number the
/// public API accepts.
/// </summary>
/// <remarks>
/// Validation runs once, at construction time. The point is that a model which passes
/// here can never fail later with a <see cref="NullReferenceException"/> or an
/// <see cref="IndexOutOfRangeException"/> from deep inside the conversion loop — the
/// error is reported next to the mistake that caused it.
/// </remarks>
internal static class LocalizationValidator
{
    private const int DigitCount = 10;
    private const int TeenCount = 9;
    private const int MaxDecimalPlaces = 6;

    public static void Validate(LocalizationModel? localization, string source)
    {
        if (localization is null)
            throw new ArgumentNullException(nameof(localization), $"The localization model ({source}) is null.");

        var numbers = localization.Numbers
            ?? throw Invalid(source, "'numbers' is missing.");

        ValidateDigitArray(numbers.Ones, "numbers.ones", source);
        ValidateDigitArray(numbers.Tens, "numbers.tens", source);
        ValidateDigitArray(numbers.Hundreds, "numbers.hundreds", source);

        if (numbers.ExactHundreds is not null)
            ValidateDigitArray(numbers.ExactHundreds, "numbers.exactHundreds", source);

        if (numbers.Scales is null || numbers.Scales.Length == 0)
            throw Invalid(source, "'numbers.scales' must contain at least one entry.");

        for (var i = 0; i < numbers.Scales.Length; i++)
        {
            if (numbers.Scales[i] is null)
                throw Invalid(source, $"'numbers.scales[{i}]' is null. Use an empty string instead.");
        }

        if (numbers.ScalesPlural is not null && numbers.ScalesPlural.Length != numbers.Scales.Length)
        {
            throw Invalid(source,
                $"'numbers.scalesPlural' must have the same length as 'numbers.scales' " +
                $"({numbers.Scales.Length}), but has {numbers.ScalesPlural.Length}.");
        }

        var settings = localization.Settings
            ?? throw Invalid(source, "'settings' is missing.");

        RequireText(settings.CurrencyFormat, "settings.currencyFormat", source);
        RequireText(settings.NumberFormat, "settings.numberFormat", source);
        RequireText(settings.ZeroWord, "settings.zeroWord", source);
        RequireText(settings.NegativeWord, "settings.negativeWord", source);

        if (settings.DecimalPlaces is < 0 or > MaxDecimalPlaces)
        {
            throw Invalid(source,
                $"'settings.decimalPlaces' must be between 0 and {MaxDecimalPlaces}, but is {settings.DecimalPlaces}.");
        }

        var special = localization.SpecialNumbers;
        var teensRequested = settings.UseTeens ?? special?.Teens is not null;

        if (teensRequested)
        {
            if (special?.Teens is null)
            {
                throw Invalid(source,
                    "'settings.useTeens' is true but 'specialNumbers.teens' is missing.");
            }

            if (special.Teens.Length != TeenCount)
            {
                throw Invalid(source,
                    $"'specialNumbers.teens' must contain exactly {TeenCount} entries (11 through 19), " +
                    $"but contains {special.Teens.Length}.");
            }

            for (var i = 0; i < special.Teens.Length; i++)
            {
                if (string.IsNullOrEmpty(special.Teens[i]))
                    throw Invalid(source, $"'specialNumbers.teens[{i}]' (the word for {i + 11}) is empty.");
            }
        }

        ValidateOverrides(special?.Special, "specialNumbers.special", source);
        ValidateOverrides(special?.SpecialBeforeScale, "specialNumbers.specialBeforeScale", source);

        if (special is not null && special.CompoundSeparator is null)
            throw Invalid(source, "'specialNumbers.compoundSeparator' is null. Use an empty string instead.");

        // The default currency is only required by Convert; ConvertWithoutCurrency works
        // without one. Validate it when present so a broken entry surfaces here.
        if (localization.Currency is not null)
            ValidateCurrency(localization.Currency, "currency", source);

        if (localization.Currencies is not null)
        {
            foreach (var pair in localization.Currencies)
            {
                if (string.IsNullOrWhiteSpace(pair.Key))
                    throw Invalid(source, "'currencies' contains an empty currency code.");

                if (pair.Value is null)
                    throw Invalid(source, $"'currencies.{pair.Key}' is null.");

                ValidateCurrency(pair.Value, $"currencies.{pair.Key}", source);
            }
        }
    }

    private static void ValidateCurrency(CurrencyModel currency, string path, string source)
    {
        if (currency.Major is null)
            throw Invalid(source, $"'{path}.major' is null. Use an empty string instead.");

        if (currency.Minor is null)
            throw Invalid(source, $"'{path}.minor' is null. Use an empty string instead.");
    }

    private static void ValidateOverrides(Dictionary<int, string>? overrides, string path, string source)
    {
        if (overrides is null)
            return;

        foreach (var pair in overrides)
        {
            if (pair.Key is < 1 or > 99)
            {
                throw Invalid(source,
                    $"'{path}' contains the key {pair.Key}. Keys override the last two digits of a group " +
                    "and must be between 1 and 99; key 0 is never consulted.");
            }

            if (string.IsNullOrEmpty(pair.Value))
                throw Invalid(source, $"'{path}[{pair.Key}]' is empty.");
        }
    }

    private static void ValidateDigitArray(string[]? values, string path, string source)
    {
        if (values is null)
            throw Invalid(source, $"'{path}' is missing.");

        if (values.Length != DigitCount)
        {
            throw Invalid(source,
                $"'{path}' must contain exactly {DigitCount} entries (index 0 unused), but contains {values.Length}.");
        }

        for (var i = 0; i < values.Length; i++)
        {
            if (values[i] is null)
                throw Invalid(source, $"'{path}[{i}]' is null. Use an empty string instead.");
        }

        for (var i = 1; i < values.Length; i++)
        {
            if (values[i].Length == 0)
                throw Invalid(source, $"'{path}[{i}]' is empty, so the digit {i} would produce no word.");
        }
    }

    private static void RequireText(string? value, string path, string source)
    {
        if (string.IsNullOrEmpty(value))
            throw Invalid(source, $"'{path}' must be specified.");
    }

    private static InvalidLocalizationException Invalid(string source, string problem) =>
        new($"Invalid localization ({source}): {problem}");
}

namespace NumWordify.Converters;

/// <summary>
/// Converts numbers to their word representation for a single locale.
/// </summary>
/// <remarks>
/// Implementations are expected to be immutable and safe to share between threads, so a
/// converter can be registered as a singleton. See <see cref="NumberToWordsConverter"/>.
/// </remarks>
public interface INumberToWordsConverter
{
    /// <summary>
    /// Converts a number to words including its currency units.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <returns>The number in words, with currency.</returns>
    string Convert(decimal number);

    /// <summary>
    /// Converts a number to words without any currency units.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <returns>The number in words, without currency.</returns>
    string ConvertWithoutCurrency(decimal number);
}

using System.Globalization;
using System.Text.RegularExpressions;
using NumWordify.Exceptions;
using NumWordify.Models;

namespace NumWordify.Converters;

/// <summary>
/// Converts numbers to their word representation using a localization ruleset.
/// </summary>
/// <remarks>
/// <para>
/// Instances are immutable and stateless: conversion keeps no per-call state on the
/// object, so a single converter can be shared freely between threads and registered as
/// a singleton. Localizations loaded from a culture name are parsed once and cached for
/// the process, which makes constructing a converter cheap enough to do per call.
/// </para>
/// <para>
/// The one caveat applies to <see cref="LocalizationModel"/> instances you build
/// yourself: the converter keeps a reference rather than a copy, so the model must not
/// be mutated after it has been handed over.
/// </para>
/// </remarks>
public sealed class NumberToWordsConverter : INumberToWordsConverter
{
    private static readonly Regex PlaceholderPattern = new(
        @"\{(whole|decimal|major|minor)\}",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    private static readonly Regex RepeatedWhitespacePattern = new(
        @"\s{2,}",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    private readonly LocalizationModel _localization;
    private readonly CurrencyModel? _overriddenCurrency;

    /// <summary>
    /// Gets the culture names shipped with the library.
    /// </summary>
    public static IReadOnlyList<string> SupportedCultures => LocalizationLoader.AvailableCultures;

    /// <summary>
    /// Determines whether the library can convert numbers for the given culture.
    /// </summary>
    /// <param name="culture">The culture code to test, for example <c>"en-US"</c>.</param>
    /// <returns><see langword="true"/> when a localization resolves for the culture.</returns>
    /// <remarks>
    /// Useful before handing over <see cref="CultureInfo.CurrentCulture"/>, which is not
    /// guaranteed to be one of the supported cultures.
    /// </remarks>
    public static bool IsCultureSupported(string? culture) => LocalizationLoader.IsSupported(culture);

    /// <summary>
    /// Determines whether the library can convert numbers for the given culture.
    /// </summary>
    /// <param name="cultureInfo">The culture to test.</param>
    /// <returns><see langword="true"/> when a localization resolves for the culture.</returns>
    public static bool IsCultureSupported(CultureInfo? cultureInfo) =>
        cultureInfo is not null && LocalizationLoader.IsSupported(cultureInfo.Name);

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a culture.
    /// </summary>
    /// <param name="culture">The culture code, for example <c>"en-US"</c>. Matching is
    /// case-insensitive and falls back to another variant of the same language.</param>
    /// <exception cref="ArgumentNullException"><paramref name="culture"/> is <see langword="null"/>.</exception>
    /// <exception cref="ArgumentException"><paramref name="culture"/> is empty or whitespace.</exception>
    /// <exception cref="LocalizationNotFoundException">No localization matches the culture.</exception>
    /// <exception cref="InvalidLocalizationException">The localization resource is invalid.</exception>
    public NumberToWordsConverter(string culture)
    {
        _localization = LocalizationLoader.Load(culture);
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a culture.
    /// </summary>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <exception cref="ArgumentNullException"><paramref name="cultureInfo"/> is <see langword="null"/>.</exception>
    /// <exception cref="ArgumentException">The culture has an empty name, as
    /// <see cref="CultureInfo.InvariantCulture"/> does.</exception>
    /// <exception cref="LocalizationNotFoundException">No localization matches the culture.</exception>
    public NumberToWordsConverter(CultureInfo cultureInfo)
        : this((cultureInfo ?? throw new ArgumentNullException(nameof(cultureInfo))).Name)
    {
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a
    /// culture, overriding the currency.
    /// </summary>
    /// <param name="culture">The culture code to use.</param>
    /// <param name="currency">The currency that replaces the locale default.</param>
    /// <exception cref="ArgumentNullException"><paramref name="currency"/> is <see langword="null"/>.</exception>
    public NumberToWordsConverter(string culture, CurrencyModel currency)
        : this(culture)
    {
        _overriddenCurrency = currency ?? throw new ArgumentNullException(nameof(currency));
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a
    /// culture, overriding the currency.
    /// </summary>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <param name="currency">The currency that replaces the locale default.</param>
    /// <exception cref="ArgumentNullException"><paramref name="currency"/> is <see langword="null"/>.</exception>
    public NumberToWordsConverter(CultureInfo cultureInfo, CurrencyModel currency)
        : this(cultureInfo)
    {
        _overriddenCurrency = currency ?? throw new ArgumentNullException(nameof(currency));
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a
    /// culture, selecting one of the currencies the locale defines.
    /// </summary>
    /// <param name="culture">The culture code to use.</param>
    /// <param name="currencyCode">An ISO 4217 code listed in the locale's <c>currencies</c> map,
    /// for example <c>"EUR"</c>.</param>
    /// <exception cref="ArgumentException">The locale does not define the currency code.</exception>
    public NumberToWordsConverter(string culture, string currencyCode)
        : this(culture)
    {
        _overriddenCurrency = ResolveCurrencyCode(_localization, culture, currencyCode);
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class for a
    /// culture, selecting one of the currencies the locale defines.
    /// </summary>
    /// <param name="cultureInfo">The culture to use.</param>
    /// <param name="currencyCode">An ISO 4217 code listed in the locale's <c>currencies</c> map.</param>
    /// <exception cref="ArgumentException">The locale does not define the currency code.</exception>
    public NumberToWordsConverter(CultureInfo cultureInfo, string currencyCode)
        : this(cultureInfo)
    {
        _overriddenCurrency = ResolveCurrencyCode(
            _localization,
            cultureInfo?.Name ?? string.Empty,
            currencyCode);
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class from a
    /// localization you supply.
    /// </summary>
    /// <param name="localization">The localization ruleset. Must not be mutated afterwards.</param>
    /// <exception cref="ArgumentNullException"><paramref name="localization"/> is <see langword="null"/>.</exception>
    /// <exception cref="InvalidLocalizationException">The localization is incomplete or inconsistent.</exception>
    public NumberToWordsConverter(LocalizationModel localization)
    {
        if (localization is null)
            throw new ArgumentNullException(nameof(localization));

        LocalizationValidator.Validate(localization, "caller-supplied LocalizationModel");
        _localization = localization;
    }

    /// <summary>
    /// Initializes a new instance of the <see cref="NumberToWordsConverter"/> class from a
    /// localization you supply, overriding the currency.
    /// </summary>
    /// <param name="localization">The localization ruleset. Must not be mutated afterwards.</param>
    /// <param name="currency">The currency that replaces the model default.</param>
    /// <exception cref="ArgumentNullException">An argument is <see langword="null"/>.</exception>
    public NumberToWordsConverter(LocalizationModel localization, CurrencyModel currency)
        : this(localization)
    {
        _overriddenCurrency = currency ?? throw new ArgumentNullException(nameof(currency));
    }

    /// <summary>
    /// Converts a number to words including its currency units.
    /// </summary>
    /// <param name="number">The number to convert. The fractional part is rounded to
    /// <see cref="SettingsModel.DecimalPlaces"/> digits, away from zero.</param>
    /// <returns>The number in words, with currency.</returns>
    /// <exception cref="NumberOutOfRangeException">The number needs more scale words than the
    /// locale defines. With the six scales shipped here the limit is 10^18 − 1.</exception>
    /// <exception cref="InvalidLocalizationException">The localization has no currency and none
    /// was supplied to the constructor.</exception>
    public string Convert(decimal number)
    {
        var currency = _overriddenCurrency ?? _localization.Currency
            ?? throw new InvalidLocalizationException(
                "This localization defines no currency. Supply a CurrencyModel to the constructor " +
                "or call ConvertWithoutCurrency instead.");

        return Render(number, _localization.Settings.CurrencyFormat, currency, DecimalReadingMode.Fraction);
    }

    /// <summary>
    /// Converts a number to words without any currency units.
    /// </summary>
    /// <param name="number">The number to convert. The fractional part is rounded to
    /// <see cref="SettingsModel.DecimalPlaces"/> digits, away from zero.</param>
    /// <returns>The number in words, without currency.</returns>
    /// <exception cref="NumberOutOfRangeException">The number needs more scale words than the
    /// locale defines. With the six scales shipped here the limit is 10^18 − 1.</exception>
    public string ConvertWithoutCurrency(decimal number) =>
        Render(number, _localization.Settings.NumberFormat, currency: null, _localization.Settings.DecimalReading);

    private string Render(decimal number, string template, CurrencyModel? currency, DecimalReadingMode readingMode)
    {
        var settings = _localization.Settings;
        var (isNegative, wholePart, fractionPart) = SplitNumberParts(number, settings.DecimalPlaces);

        var wholeWords = ConvertWholeNumber(wholePart, number);
        if (wholeWords.Length == 0)
            wholeWords = settings.ZeroWord;

        var fractionWords = readingMode == DecimalReadingMode.Digits
            ? ReadFractionDigits(fractionPart, settings.DecimalPlaces)
            : ConvertWholeNumber(fractionPart, number);
        if (fractionWords.Length == 0)
            fractionWords = settings.ZeroWord;

        // One pass over the template, so a currency name that happens to contain "{minor}"
        // is emitted literally instead of being treated as another placeholder.
        var rendered = PlaceholderPattern.Replace(template, match => match.Groups[1].Value switch
        {
            "whole" => wholeWords,
            "decimal" => fractionWords,
            "major" => currency is null ? string.Empty : Inflect(currency.Major, currency.MajorSingular, wholePart),
            "minor" => currency is null ? string.Empty : Inflect(currency.Minor, currency.MinorSingular, fractionPart),
            _ => match.Value,
        });

        // A placeholder resolving to an empty string would otherwise leave a double space.
        var result = RepeatedWhitespacePattern.Replace(rendered, " ").Trim();

        if (!isNegative)
            return result;

        return result.Length == 0
            ? settings.NegativeWord
            : settings.NegativeWord + " " + result;
    }

    private static string Inflect(string plural, string? singular, decimal value) =>
        value == 1m && !string.IsNullOrEmpty(singular) ? singular! : plural;

    private string ConvertWholeNumber(decimal value, decimal originalNumber)
    {
        if (value == 0m)
            return string.Empty;

        var scales = _localization.Numbers!.Scales;
        var groups = new List<string>();
        var remaining = value;
        var scale = 0;

        while (remaining > 0m)
        {
            var group = (int)(remaining % 1000m);
            if (group > 0)
            {
                if (scale >= scales.Length)
                    throw new NumberOutOfRangeException(originalNumber, scales.Length);

                var text = ConvertGroup(group, scale);
                if (scale > 0)
                {
                    var scaleWord = ScaleWord(scale, group);
                    text = text.Length == 0 ? scaleWord : text + " " + scaleWord;
                }

                if (text.Length > 0)
                    groups.Insert(0, text);
            }

            remaining = Math.Floor(remaining / 1000m);
            scale++;
        }

        return string.Join(" ", groups);
    }

    private string ConvertGroup(int number, int scale)
    {
        var hundreds = number / 100;
        var remainder = number % 100;
        var parts = new List<string>(2);

        if (hundreds > 0)
            parts.Add(HundredsWord(hundreds, remainder, scale));

        // A group whose last two digits are zero contributes no tens/ones word at all,
        // which is why the override maps are never consulted with a key of 0.
        if (remainder > 0)
        {
            var word = TensAndOnesWord(remainder, number, scale);
            if (word.Length > 0)
                parts.Add(word);
        }

        return string.Join(" ", parts);
    }

    private string HundredsWord(int hundreds, int remainder, int scale)
    {
        var numbers = _localization.Numbers!;

        if (remainder == 0 && numbers.ExactHundreds is { } exact)
        {
            var applies = scale == 0 || _localization.Settings.UseExactHundredsBeforeScale;
            if (applies && exact[hundreds].Length > 0)
                return exact[hundreds];
        }

        return numbers.Hundreds[hundreds];
    }

    private string TensAndOnesWord(int remainder, int groupValue, int scale)
    {
        var settings = _localization.Settings;
        var numbers = _localization.Numbers!;
        var special = _localization.SpecialNumbers;

        // "bin" rather than "bir bin", "mille" rather than "un mille".
        if (scale == 1 && groupValue == 1 && settings.SkipOneForThousand)
            return string.Empty;

        if (scale > 0 &&
            special?.SpecialBeforeScale is { } beforeScale &&
            beforeScale.TryGetValue(remainder, out var beforeScaleWord))
        {
            return beforeScaleWord;
        }

        if (special?.Special is { } overrides && overrides.TryGetValue(remainder, out var overrideWord))
            return overrideWord;

        var useTeens = settings.UseTeens ?? special?.Teens is not null;
        if (useTeens && remainder is >= 11 and <= 19 && special?.Teens is { } teens)
            return teens[remainder - 11];

        var tens = remainder / 10;
        var ones = remainder % 10;

        if (tens == 0)
            return numbers.Ones[ones];

        var word = numbers.Tens[tens];
        if (ones > 0)
            word += (special?.CompoundSeparator ?? " ") + numbers.Ones[ones];

        return word;
    }

    private string ReadFractionDigits(decimal fraction, int decimalPlaces)
    {
        if (decimalPlaces == 0 || fraction == 0m)
            return string.Empty;

        var digits = ((long)fraction)
            .ToString(CultureInfo.InvariantCulture)
            .PadLeft(decimalPlaces, '0')
            .TrimEnd('0');

        if (digits.Length == 0)
            return string.Empty;

        var numbers = _localization.Numbers!;
        var words = new List<string>(digits.Length);

        foreach (var character in digits)
        {
            var digit = character - '0';
            words.Add(digit == 0 ? _localization.Settings.ZeroWord : numbers.Ones[digit]);
        }

        return string.Join(" ", words);
    }

    private static (bool IsNegative, decimal Whole, decimal Fraction) SplitNumberParts(
        decimal number,
        int decimalPlaces)
    {
        var isNegative = number < 0m;
        var magnitude = Math.Abs(number);

        if (decimalPlaces == 0)
        {
            var rounded = Math.Round(magnitude, 0, MidpointRounding.AwayFromZero);
            return (isNegative && rounded != 0m, rounded, 0m);
        }

        var whole = Math.Floor(magnitude);
        var factor = Pow10(decimalPlaces);

        // Money rounds away from zero; the framework default (to even) would turn
        // 1.005 into one dollar zero cents.
        var fraction = Math.Round((magnitude - whole) * factor, MidpointRounding.AwayFromZero);

        if (fraction >= factor)
        {
            whole += 1m;
            fraction = 0m;
        }

        // -0.001 rounds to zero, and "negative zero" is not a thing anyone wants printed.
        if (whole == 0m && fraction == 0m)
            isNegative = false;

        return (isNegative, whole, fraction);
    }

    private static decimal Pow10(int exponent) => exponent switch
    {
        0 => 1m,
        1 => 10m,
        2 => 100m,
        3 => 1_000m,
        4 => 10_000m,
        5 => 100_000m,
        6 => 1_000_000m,
        _ => throw new ArgumentOutOfRangeException(nameof(exponent), exponent, "Supported range is 0 to 6."),
    };

    private static CurrencyModel ResolveCurrencyCode(
        LocalizationModel localization,
        string culture,
        string currencyCode)
    {
        if (currencyCode is null)
            throw new ArgumentNullException(nameof(currencyCode));

        if (localization.Currencies is { } currencies)
        {
            foreach (var pair in currencies)
            {
                if (string.Equals(pair.Key, currencyCode, StringComparison.OrdinalIgnoreCase))
                    return pair.Value;
            }
        }

        var available = localization.Currencies is null || localization.Currencies.Count == 0
            ? "none"
            : string.Join(", ", localization.Currencies.Keys.OrderBy(key => key, StringComparer.Ordinal));

        throw new ArgumentException(
            $"Culture '{culture}' does not define the currency '{currencyCode}'. Currencies defined: {available}. " +
            "Pass a CurrencyModel instead to use a currency the locale does not know.",
            nameof(currencyCode));
    }
}

