    /// locale defines.
    /// </summary>
    /// <param name="number">The number to convert.</param>
    /// <param name="culture">The culture code.</param>
    /// <param name="currencyCode">An ISO 4217 code such as <c>"EUR"</c>.</param>
    /// <returns>The number in words, with currency.</returns>
