        Assert.Equal(expected, actual);
    }

    [Theory]
    [InlineData("0.999", "ONE DOLLAR ZERO CENTS")]
    [InlineData("1.999", "TWO DOLLARS ZERO CENTS")]
    [InlineData("9.9999", "TEN DOLLARS ZERO CENTS")]
