using System.Globalization;
using NumWordify.Converters;
using NumWordify.Extensions;
using NumWordify.Models;
using Xunit;

namespace NumWordify.Tests;

/// <summary>
/// Every output shown in README.md, asserted. Seven of the eight examples in the previous
/// README did not match what the code produced, so the documentation is executable now.
/// </summary>
public class ReadmeExampleTests
{
    [Fact]
    public void Basic_usage()
    {
        const decimal amount = 1234.56M;

        Assert.Equal("BİN İKİ YÜZ OTUZ DÖRT TL ELLİ ALTI Kr", amount.ToWords("tr-TR"));
        Assert.Equal("BİN İKİ YÜZ OTUZ DÖRT TL ELLİ ALTI Kr", amount.ToWords(new CultureInfo("tr-TR")));
        Assert.Equal("BİN İKİ YÜZ OTUZ DÖRT NOKTA ELLİ ALTI", amount.ToWordsWithoutCurrency("tr-TR"));

        Assert.Equal(
            "ELEVEN THOUSAND TWO HUNDRED THIRTY-FOUR DOLLARS FIFTY-SIX CENTS",
            11234.56M.ToWords("en-US"));

        Assert.Equal(
            "MILLE DEUX CENT TRENTE-QUATRE EUROS CINQUANTE-SIX CENTIMES",
            amount.ToWords("fr-FR"));

        Assert.Equal(
            "MIL DOSCIENTOS TREINTA Y CUATRO EUROS CINCUENTA Y SEIS CÉNTIMOS",
            amount.ToWords("es-ES"));
    }

    [Fact]
    public void Currency_examples()
    {
        Assert.Equal("BİN İKİ YÜZ OTUZ DÖRT EURO ELLİ ALTI SENT", 1234.56M.ToWords("tr-TR", "EUR"));

        var currency = new CurrencyModel { Major = "EURO", Minor = "SENT" };
        Assert.Equal("BİN İKİ YÜZ OTUZ DÖRT EURO ELLİ ALTI SENT", 1234.56M.ToWords("tr-TR", currency));

        Assert.Equal("ONE DOLLAR ONE CENT", 1.01M.ToWords("en-US"));
        Assert.Equal("TWO DOLLARS TWO CENTS", 2.02M.ToWords("en-US"));
    }

    [Fact]
    public void Negative_numbers_and_zero()
    {
        Assert.Equal("EKSİ BİN İKİ YÜZ OTUZ DÖRT TL ELLİ ALTI Kr", (-1234.56M).ToWords("tr-TR"));
        Assert.Equal("SIFIR TL SIFIR Kr", 0M.ToWords("tr-TR"));
        Assert.Equal("ZERO DOLLARS ZERO CENTS", (-0.001M).ToWords("en-US"));
    }

    [Fact]
    public void Options_example()
    {
        var options = new WordifyOptions { Culture = "tr-TR", CurrencyCode = "USD" };

        Assert.Equal("BİR DOLAR SIFIR SENT", 1M.ToWords(options));
        Assert.Equal("BİR NOKTA SIFIR", 1M.ToWordsWithoutCurrency(options));
    }

    [Fact]
    public void Supported_cultures_listing()
    {
        Assert.Equal(
            ["en-US", "es-ES", "fr-FR", "tr-TR", "tr-TR-EUR"],
            NumberToWordsConverter.SupportedCultures);
    }

    [Fact]
    public void Precision_and_rounding_examples()
    {
        Assert.Equal("ONE DOLLAR ONE CENT", 1.005M.ToWords("en-US"));
        Assert.Equal("ONE DOLLAR TWENTY-THREE CENTS", 1.234567M.ToWords("en-US"));
        Assert.Equal("ONE DOLLAR TWENTY-FOUR CENTS", 1.235M.ToWords("en-US"));
        Assert.Equal("ONE DOLLAR ZERO CENTS", 0.999M.ToWords("en-US"));

        var digits = TestLocalizations.EnglishWithoutCurrency();
        digits.Settings.DecimalReading = DecimalReadingMode.Digits;

        Assert.Equal("ONE POINT FIFTY", 1.5M.ToWordsWithoutCurrency(TestLocalizations.EnglishWithoutCurrency()));
        Assert.Equal("ONE POINT FIVE", 1.5M.ToWordsWithoutCurrency(digits));
        Assert.Equal("ONE POINT TWO FIVE", 1.25M.ToWordsWithoutCurrency(digits));
    }

    [Fact]
    public void Culture_fallback_example()
    {
        var culture = NumberToWordsConverter.IsCultureSupported(CultureInfo.CurrentCulture)
            ? CultureInfo.CurrentCulture.Name
            : "en-US";

        Assert.False(string.IsNullOrWhiteSpace(1234.56M.ToWords(culture)));
    }

    [Fact]
    public void The_deprecated_euro_locale_matches_the_currency_code_form()
    {
        Assert.Equal(1234.56M.ToWords("tr-TR-EUR"), 1234.56M.ToWords("tr-TR", "EUR"));
    }

    [Fact]
    public void Custom_localization_example()
    {
        var japanese = new LocalizationModel
        {
            Currency = new CurrencyModel { Major = "YEN", Minor = "SEN" },
            Numbers = new NumbersModel
            {
                Ones = ["", "ICHI", "NI", "SAN", "YON", "GO", "ROKU", "NANA", "HACHI", "KYU"],
                Tens = ["", "JU", "NIJU", "SANJU", "YONJU", "GOJU", "ROKUJU", "NANAJU", "HACHIJU", "KYUJU"],
                Hundreds =
                [
                    "", "HYAKU", "NIHYAKU", "SANBYAKU", "YONHYAKU",
                    "GOHYAKU", "ROPPYAKU", "NANAHYAKU", "HAPPYAKU", "KYUHYAKU"
                ],
                Scales = ["", "SEN", "MAN", "OKU", "CHO", "KEI"],
            },
            Settings = new SettingsModel
            {
                SkipOneForThousand = true,
                NegativeWord = "MAINASU",
                ZeroWord = "ZERO",
                CurrencyFormat = "{whole} {major}",
                NumberFormat = "{whole} TEN {decimal}",
            },
        };

        Assert.Equal("SEN NIHYAKU SANJU YON YEN", 1234.56M.ToWords(japanese));
    }

    [Fact]
    public void Adding_a_new_language_schema_example_is_valid()
    {
        // The JSON block in the README, expressed as the model it deserializes into.
        var localization = new LocalizationModel
        {
            Currency = new CurrencyModel
            {
                Major = "DOLLARS",
                MajorSingular = "DOLLAR",
                Minor = "CENTS",
                MinorSingular = "CENT",
            },
            Currencies = new Dictionary<string, CurrencyModel>
            {
                ["EUR"] = new()
                {
                    Major = "EUROS",
                    MajorSingular = "EURO",
                    Minor = "CENTS",
                    MinorSingular = "CENT",
                },
            },
            Numbers = new NumbersModel
            {
                Ones = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"],
                Tens = ["", "TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"],
                Hundreds =
                [
                    "", "ONE HUNDRED", "TWO HUNDRED", "THREE HUNDRED", "FOUR HUNDRED",
                    "FIVE HUNDRED", "SIX HUNDRED", "SEVEN HUNDRED", "EIGHT HUNDRED", "NINE HUNDRED"
                ],
                Scales = ["", "THOUSAND", "MILLION", "BILLION", "TRILLION", "QUADRILLION"],
            },
            Settings = new SettingsModel
            {
                SkipOneForThousand = false,
                UseTeens = true,
                NegativeWord = "NEGATIVE",
                ZeroWord = "ZERO",
                CurrencyFormat = "{whole} {major} {decimal} {minor}",
                NumberFormat = "{whole} POINT {decimal}",
                DecimalPlaces = 2,
            },
            SpecialNumbers = TestLocalizations.EnglishSpecials(),
        };

        Assert.Equal("ELEVEN DOLLARS ZERO CENTS", 11M.ToWords(localization));
    }
}

using NumWordify.Converters;
using Xunit;

namespace NumWordify.Tests;

/// <summary>
/// The README claims localizations are parsed once and cached. Every <c>ToWords</c> call
/// used to scan the assembly manifest, read a stream and deserialize the whole file, so
/// this pins the claim to something checkable rather than a timing measurement.
/// </summary>
public class LocalizationCacheTests
{
    [Fact]
    public void A_locale_is_parsed_once_and_reused()
    {
        var first = LocalizationLoader.Load("en-US");
        var second = LocalizationLoader.Load("en-US");

        Assert.Same(first, second);
    }

    [Fact]
    public void Culture_spellings_that_resolve_to_the_same_file_share_one_entry()
    {
        var canonical = LocalizationLoader.Load("en-US");

        Assert.Same(canonical, LocalizationLoader.Load("EN-US"));
        Assert.Same(canonical, LocalizationLoader.Load("en"));
        Assert.Same(canonical, LocalizationLoader.Load("en-GB"));
    }

    [Fact]
    public void Different_locales_do_not_share_an_entry()
    {
        Assert.NotSame(LocalizationLoader.Load("tr-TR"), LocalizationLoader.Load("tr-TR-EUR"));
    }
}

using System.Text.Json.Serialization;

namespace NumWordify.Models;

/// <summary>
/// Grammatical class of a scale word, which decides how the group in front of it behaves.
/// </summary>
/// <remarks>
/// French needs this distinction: <c>cent</c> and <c>vingt</c> take a plural -s unless
/// another numeral adjective follows. <c>mille</c> is a numeral adjective, so the -s
/// drops (<c>DEUX CENT MILLE</c>); <c>million</c> is a noun, so it stays
/// (<c>DEUX CENTS MILLIONS</c>). Spanish needs the same distinction in the other
/// direction: the apocope in <c>UN MILLÓN</c> is the same rule as in <c>UN EURO</c>,
/// because both are nouns.
/// </remarks>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum ScaleKind
{
    /// <summary>
    /// The scale word behaves as a numeral adjective (French <c>mille</c>, Spanish <c>mil</c>).
    /// This is the default when a locale does not say otherwise.
    /// </summary>
    Adjective = 0,

    /// <summary>
    /// The scale word behaves as a noun (French <c>million</c>, Spanish <c>millón</c>).
    /// </summary>
    Noun = 1,
}

/// <summary>
/// The number words of a locale. <see cref="Ones"/>, <see cref="Tens"/> and
/// <see cref="Hundreds"/> are indexed by digit and must contain exactly ten entries,
/// with index zero left empty.
/// </summary>
public class NumbersModel
{
    /// <summary>
    /// Gets or sets the words for the ones digit. Index 0 must be empty.
    /// </summary>
    [JsonPropertyName("ones")]
    public string[] Ones { get; set; } = [];

    /// <summary>
    /// Gets or sets the words for the tens digit. Index 0 must be empty.
    /// </summary>
    [JsonPropertyName("tens")]
    public string[] Tens { get; set; } = [];

    /// <summary>
    /// Gets or sets the words for the hundreds digit. Index 0 must be empty.
    /// </summary>
    [JsonPropertyName("hundreds")]
    public string[] Hundreds { get; set; } = [];

    /// <summary>
    /// Gets or sets the hundreds words used when the last two digits are zero.
    /// Optional; entries left empty fall back to <see cref="Hundreds"/>.
    /// </summary>
    /// <remarks>
    /// Spanish needs this for <c>100 = CIEN</c> versus <c>101 = CIENTO UNO</c>, and French
    /// for <c>200 = DEUX CENTS</c> versus <c>250 = DEUX CENT CINQUANTE</c>. When set it must
    /// contain exactly ten entries, but only the ones that actually differ need a value —
    /// Spanish fills index 1 and leaves the rest empty. See
    /// <see cref="SettingsModel.UseExactHundredsBeforeScale"/> for how it interacts with
    /// scale words.
    /// </remarks>
    [JsonPropertyName("exactHundreds")]
    public string[]? ExactHundreds { get; set; }

    /// <summary>
    /// Gets or sets the scale words: index 0 is the units group, index 1 the thousands
    /// group, and so on. The array length caps the largest convertible number at
    /// 10^(3 × length) − 1. Index 0 must be empty; every other entry must have a value.
    /// </summary>
    [JsonPropertyName("scales")]
    public string[] Scales { get; set; } = [];

    /// <summary>
    /// Gets or sets the plural scale words, used when the group preceding the scale is
    /// greater than one (French <c>DEUX MILLIONS</c>, Spanish <c>DOS MILLONES</c>).
    /// Optional; entries left empty fall back to <see cref="Scales"/>. When set it must
    /// have the same length as <see cref="Scales"/>.
    /// </summary>
    [JsonPropertyName("scalesPlural")]
    public string[]? ScalesPlural { get; set; }

    /// <summary>
    /// Gets or sets the grammatical class of each scale word, parallel to
    /// <see cref="Scales"/>. Optional; every scale is treated as
    /// <see cref="ScaleKind.Adjective"/> when omitted. When set it must have the same
    /// length as <see cref="Scales"/>.
    /// </summary>
    [JsonPropertyName("scaleKinds")]
    public ScaleKind[]? ScaleKinds { get; set; }
}

