  Get-ChildItem -Path $root -Recurse -Depth 5 -Include "git-remote-entire*","entire.exe","entire.cmd" -ErrorAction SilentlyContinue |
    ForEach-Object { $found += $_.FullName }
}
if ($found.Count -eq 0) { "NOT FOUND" } else { $found | Select-Object -Unique }
